    fontFace: FONT_BODY, fontSize: 9, color: C.iceDim,
    valign: "middle", margin: 0,
  });
})();

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 2 — Language Trends (line chart data via table)
// ═══════════════════════════════════════════════════════════════════════════
