"use strict";
const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "State of Developer Ecosystem 2024";
pres.author = "JetBrains";

// ─── Palette ───────────────────────────────────────────────────────────────
// Midnight Executive: navy dominant, ice blue support, white accent
const C = {
  navy:     "1E2761",
  navyDark: "141B47",
  iceBlue:  "CADCFC",
  iceDim:   "A8C4F8",
  white:    "FFFFFF",
  offWhite: "F4F7FF",
  gray:     "64748B",
  lightGray:"E2E8F0",
  text:     "1E293B",
  accent1:  "3B82F6",  // bright blue
  accent2:  "F59E0B",  // amber
  accent3:  "10B981",  // emerald
  accent4:  "EF4444",  // red
  accent5:  "8B5CF6",  // purple
};

const FONT_TITLE = "Georgia";
const FONT_BODY  = "Calibri";

// ─── Helpers ───────────────────────────────────────────────────────────────
function slideBg(slide, dark = false) {
  slide.background = { color: dark ? C.navyDark : C.offWhite };
}

function addSlideHeader(slide, title, dark = false) {
  // colored top bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.55,
    fill: { color: dark ? C.navy : C.navy },
    line: { color: dark ? C.navy : C.navy, width: 0 },
  });
  // title text
  slide.addText(title, {
    x: 0.35, y: 0, w: 9.3, h: 0.55,
    fontFace: FONT_TITLE, fontSize: 18, bold: true,
    color: C.white, valign: "middle", margin: 0,
  });
}

function addFooter(slide, dark = false) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.375, w: 10, h: 0.25,
    fill: { color: dark ? C.navy : C.navy },
    line: { color: dark ? C.navy : C.navy, width: 0 },
  });
  slide.addText("JetBrains State of Developer Ecosystem 2024  |  N=23,262 developers", {
    x: 0.35, y: 5.375, w: 9.3, h: 0.25,
    fontFace: FONT_BODY, fontSize: 8, color: C.iceBlue,
    valign: "middle", margin: 0,
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 1 — Title / Cover
// ═══════════════════════════════════════════════════════════════════════════
(function slide1() {
  const s = pres.addSlide();
  slideBg(s, true);

  // full-width top accent band
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 1.8,
    fill: { color: C.navy }, line: { color: C.navy, width: 0 },
  });

  // bottom accent band
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.2, w: 10, h: 0.425,
    fill: { color: C.navy }, line: { color: C.navy, width: 0 },
  });

  // bright left accent bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 1.8, w: 0.12, h: 3.4,
    fill: { color: C.accent1 }, line: { color: C.accent1, width: 0 },
  });

  // Large title
  s.addText("State of Developer Ecosystem 2024", {
    x: 0.35, y: 1.9, w: 9.3, h: 1.1,
    fontFace: FONT_TITLE, fontSize: 36, bold: true,
    color: C.white, valign: "middle", margin: 0,
  });

  s.addText("Language Trends, Satisfaction & Strategic Shifts", {
    x: 0.35, y: 3.0, w: 9.3, h: 0.6,
    fontFace: FONT_BODY, fontSize: 18,
    color: C.iceBlue, valign: "middle", margin: 0,
  });

  // Stats row
  const stats = [
    { val: "23,262", lbl: "Developers Surveyed" },
    { val: "8 Years", lbl: "Longitudinal Data" },
    { val: "20+", lbl: "Languages Tracked" },
  ];
  stats.forEach((st, i) => {
    const bx = 0.35 + i * 3.1;
    s.addShape(pres.shapes.RECTANGLE, {
      x: bx, y: 3.8, w: 2.8, h: 1.1,
      fill: { color: C.navy }, line: { color: C.accent1, width: 1.5 },
    });
    s.addText(st.val, {
      x: bx, y: 3.82, w: 2.8, h: 0.55,
      fontFace: FONT_TITLE, fontSize: 26, bold: true,
      color: C.accent1, align: "center", valign: "middle", margin: 0,
    });
    s.addText(st.lbl, {
      x: bx, y: 4.37, w: 2.8, h: 0.4,
      fontFace: FONT_BODY, fontSize: 10,
      color: C.iceBlue, align: "center", valign: "top", margin: 0,
    });
  });

  // footer source line
  s.addText("Source: JetBrains State of Developer Ecosystem 2024", {
    x: 0.35, y: 5.2, w: 9.3, h: 0.35,
    fontFace: FONT_BODY, fontSize: 9, color: C.iceDim,
    valign: "middle", margin: 0,
  });
})();

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 2 — Language Trends (line chart data via table)
// ═══════════════════════════════════════════════════════════════════════════
(function slide2() {
  const s = pres.addSlide();
  slideBg(s, false);
  addSlideHeader(s, "Python Closes the Gap: 8 Years of Language Usage Shifts");
  addFooter(s);

  // Line chart: top 8 languages 2017-2024
  const years = ["2017", "2020", "2022", "2024"];
  const seriesData = [
    { name: "JavaScript", values: [65, 70, 65, 61], color: "F59E0B" },
    { name: "Python",     values: [32, 55, 53, 57], color: "10B981" },
    { name: "HTML/CSS",   values: [60, 61, 54, 51], color: "6366F1" },
    { name: "SQL",        values: [42, 56, 49, 48], color: "0EA5E9" },
    { name: "Java",       values: [47, 54, 48, 46], color: "EF4444" },
    { name: "TypeScript", values: [12, 28, 34, 37], color: "3B82F6" },
    { name: "Go",         values: [ 8, 19, 19, 18], color: "14B8A6" },
    { name: "PHP",        values: [30, 27, 20, 17], color: "8B5CF6" },
  ];

  const chartData = seriesData.map(d => ({
    name: d.name,
    labels: years,
    values: d.values,
  }));

  s.addChart(pres.charts.LINE, chartData, {
    x: 0.3, y: 0.65, w: 6.0, h: 4.6,
    chartColors: seriesData.map(d => d.color),
    chartArea: { fill: { color: C.offWhite }, roundedCorners: false },
    plotArea: { fill: { color: C.offWhite } },
    catAxisLabelColor: C.gray,
    valAxisLabelColor: C.gray,
    valAxisMinVal: 0,
    valAxisMaxVal: 75,
    valGridLine: { color: C.lightGray, size: 0.5 },
    catGridLine: { style: "none" },
    lineSize: 2.5,
    showLegend: true,
    legendPos: "b",
    legendFontSize: 9,
    legendColor: C.text,
    showTitle: false,
    dataLabelFormatCode: '0"%"',
  });

  // Key callouts on the right
  const callouts = [
    { emoji: "▲", label: "Python", note: "32% → 57%", color: C.accent3 },
    { emoji: "▲", label: "TypeScript", note: "12% → 37% (3×)", color: C.accent1 },
    { emoji: "▼", label: "JavaScript", note: "70% peak → 61%", color: C.accent2 },
    { emoji: "▼", label: "PHP", note: "30% → 17%", color: C.accent4 },
  ];

  s.addText("Key Shifts", {
    x: 6.55, y: 0.72, w: 3.1, h: 0.4,
    fontFace: FONT_TITLE, fontSize: 14, bold: true,
    color: C.navy, margin: 0,
  });

  callouts.forEach((c, i) => {
    const by = 1.2 + i * 0.88;
    s.addShape(pres.shapes.RECTANGLE, {
      x: 6.55, y: by, w: 3.1, h: 0.75,
      fill: { color: C.white },
      line: { color: C.lightGray, width: 0.5 },
      shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 },
    });
    // left accent stripe
    s.addShape(pres.shapes.RECTANGLE, {
      x: 6.55, y: by, w: 0.08, h: 0.75,
      fill: { color: c.color }, line: { color: c.color, width: 0 },
    });
    s.addText(c.emoji + " " + c.label, {
      x: 6.72, y: by + 0.04, w: 2.85, h: 0.3,
      fontFace: FONT_BODY, fontSize: 12, bold: true,
      color: C.text, valign: "middle", margin: 0,
    });
    s.addText(c.note, {
      x: 6.72, y: by + 0.37, w: 2.85, h: 0.25,
      fontFace: FONT_BODY, fontSize: 10,
      color: C.gray, valign: "middle", margin: 0,
    });
  });
})();

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 3 — Primary Language & Adoption Intent
// ═══════════════════════════════════════════════════════════════════════════
(function slide3() {
  const s = pres.addSlide();
  slideBg(s, false);
  addSlideHeader(s, "Python Is Now the #1 Primary Language at 35%");
  addFooter(s);

  // Primary language horizontal bar chart (left)
  const primaryData = [{
    name: "Primary Language",
    labels: ["SQL", "TypeScript", "JavaScript", "Java", "Python"],
    values: [17, 19, 28, 30, 35],
  }];

  s.addChart(pres.charts.BAR, primaryData, {
    x: 0.3, y: 0.65, w: 5.6, h: 3.8,
    barDir: "bar",
    chartColors: [C.accent1],
    chartArea: { fill: { color: C.offWhite } },
    plotArea: { fill: { color: C.offWhite } },
    catAxisLabelColor: C.text,
    valAxisLabelColor: C.gray,
    valAxisMaxVal: 40,
    valGridLine: { color: C.lightGray, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelFormatCode: '0"%"',
    dataLabelColor: C.text,
    dataLabelFontSize: 10,
    showLegend: false,
    showTitle: true,
    title: "Primary Language (% of devs)",
    titleColor: C.navy,
    titleFontSize: 11,
    titleFontBold: true,
  });

  // Adoption intent chart (right)
  const adoptData = [{
    name: "Plan to Adopt",
    labels: ["Java", "SQL", "TypeScript", "Python"],
    values: [4, 4, 5, 6],
  }];

  s.addChart(pres.charts.BAR, adoptData, {
    x: 6.0, y: 0.65, w: 3.7, h: 3.8,
    barDir: "bar",
    chartColors: [C.accent2],
    chartArea: { fill: { color: C.offWhite } },
    plotArea: { fill: { color: C.offWhite } },
    catAxisLabelColor: C.text,
    valAxisLabelColor: C.gray,
    valAxisMaxVal: 10,
    valGridLine: { color: C.lightGray, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelFormatCode: '0"%"',
    dataLabelColor: C.text,
    dataLabelFontSize: 10,
    showLegend: false,
    showTitle: true,
    title: "Adoption Intent (% planning to adopt)",
    titleColor: C.navy,
    titleFontSize: 11,
    titleFontBold: true,
  });

  // Insight box
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.3, y: 4.6, w: 9.4, h: 0.65,
    fill: { color: C.navy }, line: { color: C.navy, width: 0 },
  });
  s.addText("Ecosystem lock-in is strong — adoption intent stays below 6% across all languages, confirming developers rarely switch primary stacks.", {
    x: 0.5, y: 4.6, w: 9.1, h: 0.65,
    fontFace: FONT_BODY, fontSize: 11, color: C.iceBlue,
    valign: "middle", margin: 0,
  });
})();

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 4 — Developer Satisfaction (horizontal bar)
// ═══════════════════════════════════════════════════════════════════════════
(function slide4() {
  const s = pres.addSlide();
  slideBg(s, false);
  addSlideHeader(s, "TypeScript and Rust Top Developer Satisfaction, Nearly Tied at 199 vs 198");
  addFooter(s);

  const langs   = ["C", "Dart", "Shell", "Kotlin", "C++", "Lua", "Go", "Python", "Rust", "TypeScript"];
  const scores  = [86,  93,    100,    113,     113,   118,  129, 151,    198,   199];
  const colors  = langs.map(l =>
    l === "TypeScript" ? C.accent1 :
    l === "Rust"       ? C.accent4 :
    l === "Python"     ? C.accent3 :
    C.iceDim
  );

  s.addChart(pres.charts.BAR, [{
    name: "Satisfaction Score",
    labels: langs,
    values: scores,
  }], {
    x: 0.3, y: 0.65, w: 6.5, h: 4.65,
    barDir: "bar",
    barGapWidthPct: 55,
    chartColors: colors,
    chartArea: { fill: { color: C.offWhite } },
    plotArea: { fill: { color: C.offWhite } },
    catAxisLabelColor: C.text,
    catAxisLabelFontSize: 11,
    valAxisLabelColor: C.gray,
    valAxisMinVal: 0,
    valAxisMaxVal: 220,
    valGridLine: { color: C.lightGray, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelColor: C.text,
    dataLabelFontSize: 10,
    showLegend: false,
    showTitle: false,
  });

  // Insight cards on right
  const insights = [
    { label: "TypeScript", score: "199", note: "Type safety + modern DX wins developers over", color: C.accent1 },
    { label: "Rust",       score: "198", note: "Memory safety without GC — nearly tied with TS",  color: C.accent4 },
    { label: "Python",     score: "151", note: "Beloved for productivity & AI/ML dominance",       color: C.accent3 },
  ];

  s.addText("Top 3 Most Loved", {
    x: 7.0, y: 0.72, w: 2.7, h: 0.4,
    fontFace: FONT_TITLE, fontSize: 13, bold: true,
    color: C.navy, margin: 0,
  });

  insights.forEach((ins, i) => {
    const by = 1.2 + i * 1.15;
    s.addShape(pres.shapes.RECTANGLE, {
      x: 7.0, y: by, w: 2.7, h: 1.0,
      fill: { color: C.white },
      line: { color: ins.color, width: 1.5 },
    });
    s.addText(ins.label + "  " + ins.score, {
      x: 7.08, y: by + 0.05, w: 2.55, h: 0.38,
      fontFace: FONT_TITLE, fontSize: 15, bold: true,
      color: ins.color, valign: "middle", margin: 0,
    });
    s.addText(ins.note, {
      x: 7.08, y: by + 0.44, w: 2.55, h: 0.46,
      fontFace: FONT_BODY, fontSize: 9,
      color: C.gray, valign: "top", margin: 0,
    });
  });

  s.addText("Scores reflect net developer satisfaction index", {
    x: 7.0, y: 4.65, w: 2.7, h: 0.3,
    fontFace: FONT_BODY, fontSize: 8, color: C.gray,
    valign: "middle", margin: 0,
  });
})();

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 5 — Domain Specialization (table heatmap)
// ═══════════════════════════════════════════════════════════════════════════
(function slide5() {
