        options: {
          fill: { color: C.navy },
          color: C.white,
          bold: true,
          fontSize: 10,
          fontFace: FONT_BODY,
          align: "left",
          valign: "middle",
        },
      }));
    }
    const langCol = langColor[row[1]] || C.accent1;
    return [
      { text: row[0], options: { fill: { color: ri % 2 === 0 ? C.white : "F0F4FF" }, color: C.text,   fontSize: 10, fontFace: FONT_BODY, align: "left",   valign: "middle", bold: false } },
      { text: row[1], options: { fill: { color: langCol },                           color: C.white,  fontSize: 10, fontFace: FONT_BODY, align: "center", valign: "middle", bold: true  } },
      { text: row[2], options: { fill: { color: ri % 2 === 0 ? C.white : "F0F4FF" }, color: C.text,   fontSize: 10, fontFace: FONT_BODY, align: "center", valign: "middle", bold: true  } },
      { text: row[3], options: { fill: { color: ri % 2 === 0 ? C.white : "F0F4FF" }, color: C.gray,   fontSize: 9,  fontFace: FONT_BODY, align: "left",   valign: "middle", bold: false } },
    ];
  });

  s.addTable(tableRows, {
    x: 0.3, y: 0.65, w: 9.4, h: 4.65,
    colW: [3.2, 1.7, 0.85, 3.65],
    border: { pt: 0.5, color: C.lightGray },
    rowH: 0.5,
  });
})();

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 6 — Strategic Takeaways
// ═══════════════════════════════════════════════════════════════════════════
(function slide6() {
  const s = pres.addSlide();
  slideBg(s, true);

  // top header bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.7,
    fill: { color: C.navy }, line: { color: C.navy, width: 0 },
  });
  s.addText("What This Means for Your Technology Strategy in 2025", {
    x: 0.35, y: 0, w: 9.3, h: 0.7,
    fontFace: FONT_TITLE, fontSize: 18, bold: true,
    color: C.white, valign: "middle", margin: 0,
  });

  // bottom footer
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.375, w: 10, h: 0.25,
    fill: { color: C.navy }, line: { color: C.navy, width: 0 },
  });
  s.addText("JetBrains State of Developer Ecosystem 2024  |  N=23,262 developers", {
    x: 0.35, y: 5.375, w: 9.3, h: 0.25,
    fontFace: FONT_BODY, fontSize: 8, color: C.iceBlue,
    valign: "middle", margin: 0,
  });

  const takeaways = [
    {
      num: "01",
      headline: "Invest in Python for AI/ML Teams",
      body: "Python is undisputed: 31% of AI/ML, 28% of data science, 57% overall usage. It's the safest AI-team hire.",
      color: C.accent3,
    },
    {
      num: "02",
      headline: "TypeScript Is the Future of Full-Stack",
      body: "62% UI share, 37% overall, satisfaction score of 199. TypeScript investments compound across frontend and backend.",
      color: C.accent1,
    },
    {
      num: "03",
      headline: "Rust & Go Are Infrastructure Growth Plays",
      body: "Go stabilized at 18%; Rust still climbing. Both offer compiler safety for microservices and cloud-native tooling.",
      color: C.accent2,
    },
    {
      num: "04",
      headline: "Shrinking PHP & Ruby Hiring Pools",
      body: "PHP dropped 30% → 17%; Ruby 10% → 4%. Plan now for succession paths and modernization roadmaps.",
      color: C.accent4,
    },
    {
      num: "05",
      headline: "Type Safety Correlates with Retention",
      body: "Top 2 satisfaction languages (TypeScript 199, Rust 198) both prioritize type systems — a signal for DX investment.",
      color: C.accent5,
    },
  ];

  // 2-column layout: 3 left, 2 right (but 5 cards)
  const cols = [
    { x: 0.25, cards: [0, 1, 2] },
    { x: 5.15, cards: [3, 4] },
  ];

  cols.forEach(col => {
    col.cards.forEach((ci, ii) => {
      const tk = takeaways[ci];
      const by = 0.82 + ii * 1.52;
      const bh = 1.38;

      s.addShape(pres.shapes.RECTANGLE, {
        x: col.x, y: by, w: 4.7, h: bh,
        fill: { color: C.navy }, line: { color: tk.color, width: 1.5 },
      });
      // left accent bar
      s.addShape(pres.shapes.RECTANGLE, {
        x: col.x, y: by, w: 0.1, h: bh,
        fill: { color: tk.color }, line: { color: tk.color, width: 0 },
      });
      // number badge
      s.addText(tk.num, {
        x: col.x + 0.18, y: by + 0.08, w: 0.5, h: 0.38,
        fontFace: FONT_TITLE, fontSize: 20, bold: true,
        color: tk.color, valign: "middle", margin: 0,
      });
      s.addText(tk.headline, {
        x: col.x + 0.72, y: by + 0.08, w: 3.85, h: 0.38,
        fontFace: FONT_TITLE, fontSize: 12, bold: true,
        color: C.white, valign: "middle", margin: 0,
      });
      s.addText(tk.body, {
        x: col.x + 0.18, y: by + 0.52, w: 4.38, h: 0.8,
        fontFace: FONT_BODY, fontSize: 10,
        color: C.iceBlue, valign: "top", margin: 0,
      });
    });
  });
})();

// ─── Save ──────────────────────────────────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Saved: /app/output/final_deck.pptx"))
  .catch(err => { console.error(err); process.exit(1); });

