    color: C.accent5,
  },
];

// 2-column layout: col1 x=0.25 (cards 0,1,2), col2 x=5.15 (cards 3,4)
// All 5 cards same height, but col2 cards are spaced to vertically center
const cardH = 1.22;
const col1Gap = 0.12;
const col2Gap = 0.45;
const col1Y = 0.82;
const col2Y = 0.82 + cardH * 0.5 + 0.05; // vertically offset to balance

[[0, 1, 2], [3, 4]].forEach((cards, ci) => {
  const cx = ci === 0 ? 0.25 : 5.15;
  const gap = ci === 0 ? col1Gap : col2Gap;
  const startY = ci === 0 ? col1Y : col2Y;
  cards.forEach((idx, ii) => {
    const tk = takeaways[idx];
    const by = startY + ii * (cardH + gap);

    s.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: by, w: 4.7, h: cardH,
      fill: { color: C.navy }, line: { color: tk.color, width: 1.5 },
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: by, w: 0.1, h: cardH,
      fill: { color: tk.color }, line: { color: tk.color, width: 0 },
